// slide-01.js — Cover Page: Cloudflare Radar 2024 Year in Review
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Cloudflare Radar 2024 Year in Review'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Decorative top bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.06,
    fill: { color: theme.accent }
  });

  // Large "2024" background text
  slide.addText("2024", {
    x: 5.5, y: 0.4, w: 4.2, h: 4.0,
    fontSize: 150, fontFace: "Georgia",
    color: theme.secondary, bold: true,
    align: "right", valign: "top",
    transparency: 70
  });

  // Accent line left of title
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 1.5, w: 0.06, h: 2.2,
    fill: { color: theme.accent }
  });

  // Main title
  slide.addText("Cloudflare Radar", {
    x: 0.85, y: 1.5, w: 5.5, h: 1.0,
    fontSize: 48, fontFace: "Georgia",
    color: theme.light, bold: true,
    align: "left", valign: "top",
    margin: 0
  });

  slide.addText("2024 Year in Review", {
    x: 0.85, y: 2.4, w: 5.5, h: 0.8,
    fontSize: 36, fontFace: "Georgia",
    color: theme.accent, bold: true,
    align: "left", valign: "top",
    margin: 0
  });

  // Subtitle / description
  slide.addText("A data-driven analysis of global Internet traffic,\nadoption trends, connectivity disruptions, and\nsecurity threats observed through Cloudflare's network.", {
    x: 0.85, y: 3.3, w: 5.0, h: 1.2,
    fontSize: 14, fontFace: "Calibri",
    color: theme.light, bold: false,
    align: "left", valign: "top",
    lineSpacingMultiple: 1.4,
    margin: 0
  });

  // Bottom decorative bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.56, w: 10, h: 0.065,
    fill: { color: theme.accent }
  });

  // Source attribution
  slide.addText("Source: Cloudflare Radar  |  radar.cloudflare.com/year-in-review/2024", {
    x: 0.6, y: 5.0, w: 5, h: 0.4,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false,
    align: "left", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "023047",
    secondary: "219ebc",
    accent: "ffb703",
    light: "8ecae6",
    bg: "023047"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

