// slide-05.js — Content: 225 Major Disruptions: Government Shutdowns Lead Outage Causes
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: '225 Major Disruptions: Government Shutdowns Lead Outage Causes'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("225 Major Disruptions: Government Shutdowns Lead Outage Causes", {
    x: 0.4, y: 0.25, w: 9.2, h: 0.65,
    fontSize: 24, fontFace: "Georgia",
    color: theme.accent, bold: true,
    align: "left", valign: "middle",
    margin: 0, fit: "shrink"
  });

  // Divider line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 0.95, w: 9.2, h: 0.02,
    fill: { color: theme.secondary, transparency: 50 }
  });

  // LEFT — Bar chart visualization using shapes
  const causes = [
    { name: "Government Directed", count: 116, highlight: true },
    { name: "Cable Cut", count: 41, highlight: false },
    { name: "Unknown", count: 16, highlight: false },
    { name: "Power Outage", count: 16, highlight: false },
    { name: "Technical Problem", count: 9, highlight: false },
    { name: "Military Action", count: 9, highlight: false },
    { name: "Weather", count: 8, highlight: false },
    { name: "Maintenance", count: 4, highlight: false },
    { name: "Cyber Attack", count: 4, highlight: false },
    { name: "Natural Disaster", count: 1, highlight: false },
    { name: "Fire", count: 1, highlight: false }
  ];

  const maxCount = 116;
  const chartLeft = 2.0;
  const chartWidth = 3.0;
  const startY = 1.15;
  const barHeight = 0.28;
  const gap = 0.04;

  causes.forEach((item, i) => {
    const y = startY + i * (barHeight + gap);
    const barW = (item.count / maxCount) * chartWidth;
    const barColor = item.highlight ? theme.accent : theme.secondary;
    const textColor = item.highlight ? theme.accent : theme.light;

    // Label
    slide.addText(item.name, {
      x: 0.4, y: y, w: 1.5, h: barHeight,
      fontSize: 9, fontFace: "Calibri",
      color: textColor, bold: item.highlight,
      align: "right", valign: "middle",
      margin: 0
    });

    // Bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: chartLeft, y: y + 0.04, w: barW, h: barHeight - 0.08,
      fill: { color: barColor },
      rectRadius: 0.02
    });

    // Count label
    slide.addText(String(item.count), {
      x: chartLeft + barW + 0.05, y: y, w: 0.6, h: barHeight,
      fontSize: 9, fontFace: "Calibri",
      color: textColor, bold: item.highlight,
      align: "left", valign: "middle",
      margin: 0
    });
  });

  // Total callout
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.4, y: 4.55, w: 4.8, h: 0.5,
    fill: { color: theme.primary },
    line: { color: theme.accent, width: 1.5 },
    rectRadius: 0.03
  });
  slide.addText([
    { text: "225 ", options: { bold: true, color: theme.accent, fontSize: 22, fontFace: "Georgia" } },
    { text: "total major Internet disruptions observed globally in 2024", options: { bold: false, color: theme.light, fontSize: 12, fontFace: "Calibri" } }
  ], {
    x: 0.5, y: 4.55, w: 4.6, h: 0.5,
    align: "left", valign: "middle",
    margin: 0
  });

  // RIGHT — Image
  slide.addImage({
    path: "./imgs/internet-disruption-causes.jpg",
    x: 5.5, y: 1.15, w: 4.1, h: 3.0,
    sizing: { type: 'contain', w: 4.1, h: 3.0 }
  });

  slide.addText("Causes of major Internet disruptions observed in 2024", {
    x: 5.5, y: 4.15, w: 4.1, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false,
    align: "center", valign: "top"
  });

  // Additional context
  slide.addText("41% of global traffic came from mobile devices. Spain recorded the highest download speed among all countries measured.", {
    x: 5.5, y: 4.55, w: 4.1, h: 0.5,
    fontSize: 10, fontFace: "Calibri",
    color: theme.light, bold: false,
    align: "left", valign: "middle"
  });

  // Source
  slide.addText("Source: Cloudflare Radar Outage Center 2024", {
    x: 0.4, y: 5.2, w: 5, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, bold: false,
    align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "000000", bold: true,
    align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = {
    primary: "023047",
    secondary: "219ebc",
    accent: "ffb703",
    light: "8ecae6",
    bg: "023047"
  };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

