      x: 1.2, y: y + 0.08, w: 8.2, h: 0.3,
      fontSize: 15, fontFace: "Georgia",
      color: theme.light, bold: true,
      align: "left", valign: "middle",
      margin: 0
    });

    // Description
    slide.addText(item.desc, {
      x: 1.2, y: y + 0.38, w: 8.2, h: 0.35,
      fontSize: 11, fontFace: "Calibri",
      color: theme.secondary, bold: false,
      align: "left", valign: "top",
      margin: 0
    });
  });

  // Bottom bar
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.3, w: 10, h: 0.325,
    fill: { color: theme.primary }
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.3, w: 10, h: 0.04,
    fill: { color: theme.accent }
  });

  slide.addText("Cloudflare Radar 2024  |  radar.cloudflare.com", {
    x: 0.4, y: 5.32, w: 6, h: 0.28,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false,
    align: "left", valign: "middle"
  });

  // Page number badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.accent }
  });
  slide.addText("7", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
